25	// Init starts the API server.
26	func Init(configPath string, port int) error {
27		return InitWithOptions(InitOptions{
28			ConfigPath: configPath,
29			Port:       port,
30		})
31	}
32	
33	// InitOptions carries management listener startup overrides.
34	type InitOptions struct {
35		ConfigPath      string
36		Port            int
37		BindAddress     string
38		RemoteExposure  *bool
39		AuthMode        string
40		RuntimeRegistry *routerruntime.Registry
41	}
42	
43	// InitWithRuntime starts the API server using the shared runtime registry when
44	// one is available. Legacy callers can continue using Init and fall back to the
45	// compatibility globals.
46	func InitWithRuntime(configPath string, port int, runtimeRegistry *routerruntime.Registry) error {
47		return InitWithOptions(InitOptions{
48			ConfigPath:      configPath,
49			Port:            port,
50			RuntimeRegistry: runtimeRegistry,
51		})
52	}
53	
54	// InitWithOptions starts the API server with explicit management listener policy.
55	func InitWithOptions(opts InitOptions) error {
56		// Get the global configuration instead of loading from file
57		// This ensures we use the same config as the rest of the application
58		cfg := resolveAPIServerConfig(opts.RuntimeRegistry)
59		if cfg == nil {
60			return fmt.Errorf("configuration not initialized")
61		}
62	
63		managementCfg, err := cfg.ManagementAPI.ResolvedManagementAPI(config.ManagementAPIRuntimeOptions{
64			Port:           opts.Port,
65			BindAddress:    opts.BindAddress,
66			RemoteExposure: opts.RemoteExposure,
67			AuthMode:       opts.AuthMode,
68		})
69		if err != nil {
70			return fmt.Errorf("invalid management API configuration: %w", err)
71		}
72		cfg.ManagementAPI = managementCfg
73	
74		classificationSvc := resolveClassificationService(cfg, opts.RuntimeRegistry)
75		classificationSvc = ensureClassificationService(cfg, opts.RuntimeRegistry, classificationSvc)
76	
77		// Initialize batch metrics configuration
78		if cfg.API.BatchClassification.Metrics.Enabled {
79			metricsConfig := metrics.BatchMetricsConfig{
80				Enabled:                   cfg.API.BatchClassification.Metrics.Enabled,
81				DetailedGoroutineTracking: cfg.API.BatchClassification.Metrics.DetailedGoroutineTracking,
82				DurationBuckets:           cfg.API.BatchClassification.Metrics.DurationBuckets,
83				SizeBuckets:               cfg.API.BatchClassification.Metrics.SizeBuckets,
84				BatchSizeRanges:           cfg.API.BatchClassification.Metrics.BatchSizeRanges,
85				HighResolutionTiming:      cfg.API.BatchClassification.Metrics.HighResolutionTiming,
86				SampleRate:                cfg.API.BatchClassification.Metrics.SampleRate,
87			}
88			metrics.SetBatchMetricsConfig(metricsConfig)
89		}
90	
91		// Get memory store if available (set by ExtProc router during init)
92		var memoryStore memory.Store
93		if shouldInitMemoryStore(cfg) {
94			memoryStore = resolveMemoryStore(cfg, opts.RuntimeRegistry)
95			if memoryStore != nil {
96				logging.ComponentEvent("apiserver", "memory_api_enabled", map[string]interface{}{})
97			} else {
98				logging.ComponentWarnEvent("apiserver", "memory_api_degraded", map[string]interface{}{
99					"reason": "memory_store_unavailable",
100					"status": 503,
101				})
102			}
103		} else {
104			logging.ComponentEvent("apiserver", "memory_api_disabled", map[string]interface{}{
105				"reason": "config_disabled",
106			})
107		}
108	
109		liveClassificationSvc := newLiveClassificationService(
110			classificationSvc,
111			buildClassificationResolver(opts.RuntimeRegistry),
112		)
113	
114		// Create server instance
115		apiServer := &ClassificationAPIServer{
116			classificationSvc:     liveClassificationSvc,
117			config:                cfg,
118			runtimeConfig:         newLiveRuntimeConfig(cfg, buildConfigResolver(opts.RuntimeRegistry), buildConfigUpdater(opts.RuntimeRegistry, liveClassificationSvc)),
119			runtimeRegistry:       opts.RuntimeRegistry,
120			configPath:            opts.ConfigPath,
121			memoryStore:           memoryStore,
122			knowledgeBaseMapCache: newKnowledgeBaseMapCache(),
123			startupStatusConfig:   &cfg.StartupStatus,
124		}
125	
126		// Create HTTP server with routes
127		mux := apiServer.setupRoutes()
128		server := &http.Server{
129			Addr:         managementCfg.ListenAddress(),
130			Handler:      mux,
131			ReadTimeout:  apiReadTimeout,
132			WriteTimeout: apiWriteTimeout,
133			IdleTimeout:  apiIdleTimeout,
134		}
135	
136		logging.ComponentEvent("apiserver", "server_listening", map[string]interface{}{
137			"address":         managementCfg.ListenAddress(),
138			"bind_address":    managementCfg.BindAddress,
139			"port":            managementCfg.Port,
140			"remote_exposure": managementCfg.RemoteExposure,
141			"auth_mode":       managementCfg.Auth.Mode,
142		})
143		return server.ListenAndServe()
144	}
145	
146	func resolveAPIServerConfig(runtimeRegistry *routerruntime.Registry) *config.RouterConfig {
147		if runtimeRegistry != nil {
148			return runtimeRegistry.CurrentConfig()
149		}
150		return config.Get()
151	}
152	
153	func resolveClassificationService(
154		cfg *config.RouterConfig,
155		runtimeRegistry *routerruntime.Registry,
156	) *services.ClassificationService {
157		if runtimeRegistry != nil {
158			return runtimeRegistry.ClassificationService()
159		}
160		return initClassify(5, 500*time.Millisecond)
161	}
162	
163	func ensureClassificationService(
164		cfg *config.RouterConfig,
165		runtimeRegistry *routerruntime.Registry,
166		svc *services.ClassificationService,
167	) *services.ClassificationService {
168		if svc != nil {
169			return svc
170		}
171	
172		if runtimeRegistry != nil {
173			logging.ComponentEvent("apiserver", "classification_service_waiting_for_runtime", map[string]interface{}{
174				"using_placeholder": true,
175			})
176			return services.NewPlaceholderClassificationService()
177		}
178	
179		// If no global service exists, try auto-discovery unified classifier.
180		logging.ComponentEvent("apiserver", "classification_service_autodiscovery_started", map[string]interface{}{})
181		autoSvc, err := services.NewClassificationServiceWithAutoDiscovery(cfg)
182		if err != nil {
183			logging.ComponentWarnEvent("apiserver", "classification_service_autodiscovery_failed", map[string]interface{}{
184				"error":             err.Error(),
185				"using_placeholder": true,
186			})
187			return services.NewPlaceholderClassificationService()
188		}
189	
190		logging.ComponentEvent("apiserver", "classification_service_autodiscovery_succeeded", map[string]interface{}{})
191		return autoSvc
