193	
194	func resolveMemoryStore(cfg *config.RouterConfig, runtimeRegistry *routerruntime.Registry) memory.Store {
195		if runtimeRegistry != nil {
196			return runtimeRegistry.MemoryStore()
197		}
198		return initMemoryStore(5, 500*time.Millisecond)
199	}
200	
201	// buildClassificationResolver returns the resolver used by the live
202	// classification service. Both sources return a concrete
203	// *services.ClassificationService which is nil until the runtime finishes
204	// initializing; returning that nil pointer directly would wrap it into a
205	// non-nil interface value, defeat the nil check in
206	// liveClassificationService.current(), and panic with a nil receiver on the
207	// first request. Return an untyped nil instead so current() falls back to
208	// the placeholder service.
209	func buildClassificationResolver(runtimeRegistry *routerruntime.Registry) func() classificationService {
210		return func() classificationService {
211			if runtimeRegistry != nil {
212				if svc := runtimeRegistry.ClassificationService(); svc != nil {
213					return svc
214				}
215				return nil
216			}
217			if svc := services.GetGlobalClassificationService(); svc != nil {
218				return svc
219			}
220			return nil
221		}
222	}
223	
224	func buildConfigResolver(runtimeRegistry *routerruntime.Registry) func() *config.RouterConfig {
225		if runtimeRegistry == nil {
226			return config.Get
227		}
228		return runtimeRegistry.CurrentConfig
229	}
230	
231	func buildConfigUpdater(
232		runtimeRegistry *routerruntime.Registry,
233		liveClassificationSvc classificationService,
234	) func(*config.RouterConfig) {
235		if runtimeRegistry == nil {
236			return func(newCfg *config.RouterConfig) {
237				if liveClassificationSvc != nil {
238					liveClassificationSvc.RefreshRuntimeConfig(newCfg)
239				}
240				config.Replace(newCfg)
241			}
242		}
243		return runtimeRegistry.RefreshRuntimeConfig
244	}
245	
246	// initClassify attempts to get the global classification service with retry logic
247	func initClassify(maxRetries int, retryInterval time.Duration) *services.ClassificationService {
248		for i := 0; i < maxRetries; i++ {
249			if svc := services.GetGlobalClassificationService(); svc != nil {
250				return svc
251			}
252	
253			if i < maxRetries-1 { // Don't sleep on the last attempt
254				logging.ComponentDebugEvent("apiserver", "classification_service_retry_pending", map[string]interface{}{
255					"retry_interval_ms": retryInterval.Milliseconds(),
256					"attempt":           i + 1,
257					"max_retries":       maxRetries,
258				})
259				time.Sleep(retryInterval)
260			}
261		}
262	
263		logging.ComponentWarnEvent("apiserver", "classification_service_unavailable", map[string]interface{}{
264			"max_retries": maxRetries,
265		})
266		return nil
267	}
268	
269	// initMemoryStore attempts to get the global memory store with retry logic.
270	// The memory store is created by the ExtProc router which may start concurrently.
271	func initMemoryStore(maxRetries int, retryInterval time.Duration) memory.Store {
272		for i := 0; i < maxRetries; i++ {
273			if store := memory.GetGlobalMemoryStore(); store != nil {
274				return store
275			}
276	
277			if i < maxRetries-1 {
278				logging.ComponentDebugEvent("apiserver", "memory_store_retry_pending", map[string]interface{}{
279					"retry_interval_ms": retryInterval.Milliseconds(),
280					"attempt":           i + 1,
281					"max_retries":       maxRetries,
282				})
283				time.Sleep(retryInterval)
284			}
285		}
286	
287		logging.ComponentWarnEvent("apiserver", "memory_store_unavailable", map[string]interface{}{
288			"max_retries": maxRetries,
289		})
290		return nil
291	}
292	
293	func shouldInitMemoryStore(cfg *config.RouterConfig) bool {
294		if cfg == nil {
295			return false
296		}
297		if cfg.Memory.Enabled {
298			return true
299		}
300		for _, decision := range cfg.Decisions {
301			if decision.HasPlugin("memory") {
302				return true
303			}
304		}
305		return false
306	}
307	
308	// setupRoutes configures all API routes
309	func (s *ClassificationAPIServer) setupRoutes() *http.ServeMux {
310		mux := http.NewServeMux()
311		for _, route := range apiRoutes() {
312			mux.HandleFunc(route.pattern(), route.bind(s))
313		}
314		return mux
315	}
316	
317	// handleHealth handles health check requests
318	func (s *ClassificationAPIServer) handleHealth(w http.ResponseWriter, _ *http.Request) {
319		w.Header().Set("Content-Type", "application/json")
320		w.WriteHeader(http.StatusOK)
321		_, _ = w.Write([]byte(`{"status": "healthy", "service": "classification-api"}`))
322	}
323	
324	// handleReady reports whether router startup has completed enough for traffic.
325	func (s *ClassificationAPIServer) handleReady(w http.ResponseWriter, _ *http.Request) {
326		w.Header().Set("Content-Type", "application/json")
327	
328		state := s.loadStartupState()
329		if state == nil {
330			w.WriteHeader(http.StatusServiceUnavailable)
331			_, _ = w.Write([]byte(`{"status":"starting","service":"classification-api","ready":false}`))
332			return
333		}
334	
335		if !state.Ready {
336			s.writeJSONResponse(w, http.StatusServiceUnavailable, map[string]interface{}{
337				"status":            "starting",
338				"service":           "classification-api",
339				"ready":             false,
340				"phase":             state.Phase,
341				"message":           state.Message,
342				"downloading_model": state.DownloadingModel,
343				"pending_models":    state.PendingModels,
344				"ready_models":      state.ReadyModels,
345				"total_models":      state.TotalModels,
346			})
347			return
348		}
349	
350		s.writeJSONResponse(w, http.StatusOK, map[string]interface{}{
351			"status":            "ready",
352			"service":           "classification-api",
353			"ready":             true,
354			"phase":             state.Phase,
355			"message":           state.Message,
356			"downloading_model": state.DownloadingModel,
357			"pending_models":    state.PendingModels,
358			"ready_models":      state.ReadyModels,
359			"total_models":      state.TotalModels,
360		})
361	}
362	
363	func (s *ClassificationAPIServer) writeJSONResponse(w http.ResponseWriter, statusCode int, data interface{}) {
364		payload, err := json.Marshal(data)
365		if err != nil {
366			logging.Errorf("Failed to encode JSON response: %v", err)
367			s.writeJSONEncodingError(w)
368			return
369		}
370	
371		w.Header().Set("Content-Type", "application/json")
372		w.WriteHeader(statusCode)
373		if _, err := w.Write(append(payload, '\n')); err != nil {
374			logging.Errorf("Failed to write JSON response: %v", err)
375		}
376	}
377	
378	func (s *ClassificationAPIServer) writeJSONEncodingError(w http.ResponseWriter) {
379		payload, err := json.Marshal(map[string]interface{}{
380			"error": map[string]interface{}{
381				"code":      "JSON_ENCODE_ERROR",
382				"message":   "failed to encode response",
383				"timestamp": time.Now().UTC().Format(time.RFC3339),
384			},
385		})
386		if err != nil {
387			logging.Errorf("Failed to encode JSON error response: %v", err)
388			http.Error(w, "failed to encode response", http.StatusInternalServerError)
389			return
390		}
391	
392		w.Header().Set("Content-Type", "application/json")
393		w.WriteHeader(http.StatusInternalServerError)
394		if _, err := w.Write(append(payload, '\n')); err != nil {
395			logging.Errorf("Failed to write JSON error response: %v", err)
396		}
397	}
398	
399	func (s *ClassificationAPIServer) writeErrorResponse(w http.ResponseWriter, statusCode int, errorCode, message string) {
400		errorResponse := map[string]interface{}{
401			"error": map[string]interface{}{
402				"code":      errorCode,
403				"message":   scrubSecretsInErrorMessage(message),
404				"timestamp": time.Now().UTC().Format(time.RFC3339),
405			},
406		}
407	
408		s.writeJSONResponse(w, statusCode, errorResponse)
409	}
