3	package apiserver
4	
5	import (
6		"fmt"
7		"net/http"
8		"os"
9		"slices"
10		"strings"
11	
12		routerconfig "github.com/vllm-project/semantic-router/src/semantic-router/pkg/config"
13	)
14	
15	type managedRecipeSource string
16	
17	const (
18		managedRecipeSourceDefault managedRecipeSource = "routing"
19		managedRecipeSourceNamed   managedRecipeSource = "recipes"
20	)
21	
22	type recipeMutationRequest struct {
23		Name        string         `json:"name,omitempty"`
24		Description *string        `json:"description,omitempty"`
25		Routing     map[string]any `json:"routing"`
26		Entrypoints *[]string      `json:"entrypoints,omitempty"`
27	}
28	
29	type managedRecipeRecord struct {
30		Name        string              `json:"name"`
31		Description string              `json:"description,omitempty"`
32		Routing     map[string]any      `json:"routing"`
33		Entrypoints []string            `json:"entrypoints"`
34		Source      managedRecipeSource `json:"source"`
35		Deletable   bool                `json:"deletable"`
36	}
37	
38	type recipeCollectionResponse struct {
39		ETag    string                `json:"etag"`
40		Recipes []managedRecipeRecord `json:"recipes"`
41	}
42	
43	// handleListRecipes exposes the normalized management view without forcing a
44	// client to download and reshape the whole canonical document.
45	func (s *ClassificationAPIServer) handleListRecipes(w http.ResponseWriter, r *http.Request) {
46		doc, data, ok := s.readManagedConfigDocument(w)
47		if !ok {
48			return
49		}
50	
51		etag := configDocumentETag(data)
52		w.Header().Set("ETag", etag)
53		response := recipeCollectionResponse{
54			ETag:    etag,
55			Recipes: collectManagedRecipes(doc),
56		}
57		response.Recipes = s.maybeRedactManagedRecipes(r, response.Recipes)
58		s.writeJSONResponse(w, http.StatusOK, response)
59	}
60	
61	func (s *ClassificationAPIServer) handleGetRecipe(w http.ResponseWriter, r *http.Request) {
62		name := strings.TrimSpace(r.PathValue("name"))
63		if name == "" {
64			s.writeErrorResponse(w, http.StatusBadRequest, "INVALID_RECIPE_NAME", "recipe name is required")
65			return
66		}
67	
68		doc, data, ok := s.readManagedConfigDocument(w)
69		if !ok {
70			return
71		}
72		recipe, found := findManagedRecipe(doc, name)
73		if !found {
74			s.writeErrorResponse(w, http.StatusNotFound, "RECIPE_NOT_FOUND", fmt.Sprintf("Recipe %q does not exist", name))
75			return
76		}
77	
78		w.Header().Set("ETag", configDocumentETag(data))
79		recipe = s.maybeRedactManagedRecipes(r, []managedRecipeRecord{recipe})[0]
80		s.writeJSONResponse(w, http.StatusOK, recipe)
81	}
82	
83	// handleValidateRecipe performs the exact document-level validation used by a
84	// live mutation, but does not create a backup or write either config path.
85	func (s *ClassificationAPIServer) handleValidateRecipe(w http.ResponseWriter, r *http.Request) {
86		var req recipeMutationRequest
87		if err := s.parseJSONRequest(r, &req); err != nil {
88			s.writeJSONRequestError(w, err)
89			return
90		}
91		name := strings.TrimSpace(req.Name)
92		if name == "" {
93			s.writeErrorResponse(w, http.StatusBadRequest, "INVALID_RECIPE_NAME", "name is required")
94			return
95		}
96	
97		doc, _, ok := s.readManagedConfigDocument(w)
98		if !ok {
99			return
100		}
101		created, err := applyRecipeMutation(doc, name, req)
102		if err != nil {
103			s.writeErrorResponse(w, http.StatusBadRequest, "INVALID_RECIPE", err.Error())
104			return
105		}
106		if _, err := validateAndEncodeRouterConfigDocument(doc); err != nil {
107			s.writeErrorResponse(w, http.StatusBadRequest, "CONFIG_VALIDATION_ERROR", err.Error())
108			return
109		}
110	
111		s.writeJSONResponse(w, http.StatusOK, map[string]any{
112			"valid":  true,
113			"name":   name,
114			"action": map[bool]string{true: "create", false: "replace"}[created],
115		})
116	}
117	
118	func (s *ClassificationAPIServer) handlePutRecipe(w http.ResponseWriter, r *http.Request) {
119		name := strings.TrimSpace(r.PathValue("name"))
120		if name == "" {
121			s.writeErrorResponse(w, http.StatusBadRequest, "INVALID_RECIPE_NAME", "recipe name is required")
122			return
123		}
124		if !deployMu.TryLock() {
125			s.writeErrorResponse(w, http.StatusConflict, "DEPLOY_IN_PROGRESS", "Another config update operation is in progress. Please try again.")
126			return
127		}
128		defer deployMu.Unlock()
129	
130		var req recipeMutationRequest
131		if err := s.parseJSONRequest(r, &req); err != nil {
132			s.writeJSONRequestError(w, err)
133			return
134		}
135		if requestName := strings.TrimSpace(req.Name); requestName != "" && requestName != name {
136			s.writeErrorResponse(w, http.StatusBadRequest, "RECIPE_NAME_MISMATCH", "body name must match the recipe name in the path")
137			return
138		}
139	
140		doc, existingData, ok := s.readManagedConfigDocument(w)
141		if !ok || !checkConfigPrecondition(w, r, existingData, true) {
142			return
143		}
144		created, err := applyRecipeMutation(doc, name, req)
145		if err != nil {
146			s.writeErrorResponse(w, http.StatusBadRequest, "INVALID_RECIPE", err.Error())
147			return
148		}
149		yamlBytes, err := validateAndEncodeRouterConfigDocument(doc)
150		if err != nil {
151			s.writeErrorResponse(w, http.StatusBadRequest, "CONFIG_VALIDATION_ERROR", err.Error())
152			return
153		}
154	
155		statusCode := http.StatusOK
156		action := "recipe.replace"
157		verb := "replaced"
158		if created {
159			statusCode = http.StatusCreated
160			action = "recipe.create"
161			verb = "created"
162		}
163		paths := resolveConfigPersistencePaths(s.configPath)
164		s.commitRouterConfigDocument(
165			w,
166			paths,
167			existingData,
168			yamlBytes,
169			"",
170			statusCode,
171			action,
172			fmt.Sprintf("Recipe %q %s successfully.", name, verb),
173		)
174	}
175	
176	func (s *ClassificationAPIServer) handleDeleteRecipe(w http.ResponseWriter, r *http.Request) {
177		name := strings.TrimSpace(r.PathValue("name"))
178		if name == "" {
179			s.writeErrorResponse(w, http.StatusBadRequest, "INVALID_RECIPE_NAME", "recipe name is required")
180			return
181		}
182		if routerconfig.RecipeName(name) == routerconfig.DefaultRecipeName {
183			s.writeErrorResponse(w, http.StatusConflict, "DEFAULT_RECIPE_REQUIRED", "The default recipe is the top-level routing profile and cannot be deleted")
184			return
185		}
186		if !deployMu.TryLock() {
187			s.writeErrorResponse(w, http.StatusConflict, "DEPLOY_IN_PROGRESS", "Another config update operation is in progress. Please try again.")
188			return
189		}
190		defer deployMu.Unlock()
191	
192		doc, existingData, ok := s.readManagedConfigDocument(w)
193		if !ok || !checkConfigPrecondition(w, r, existingData, true) {
194			return
195		}
196		entrypoints := recipeEntrypointNames(doc, name)
197		if len(entrypoints) > 0 {
198			s.writeErrorResponse(
199				w,
200				http.StatusConflict,
201				"RECIPE_IN_USE",
202				fmt.Sprintf("Recipe %q is still referenced by entrypoints %s; replace or remove those mappings first", name, strings.Join(entrypoints, ", ")),
203			)
204			return
205		}
206		if !removeNamedRecipe(doc, name) {
207			s.writeErrorResponse(w, http.StatusNotFound, "RECIPE_NOT_FOUND", fmt.Sprintf("Recipe %q does not exist", name))
208			return
209		}
210	
211		yamlBytes, err := validateAndEncodeRouterConfigDocument(doc)
212		if err != nil {
213			s.writeErrorResponse(w, http.StatusBadRequest, "CONFIG_VALIDATION_ERROR", err.Error())
214			return
215		}
216		paths := resolveConfigPersistencePaths(s.configPath)
217		s.commitRouterConfigDocument(
218			w,
219			paths,
220			existingData,
221			yamlBytes,
222			"",
223			http.StatusOK,
224			"recipe.delete",
225			fmt.Sprintf("Recipe %q deleted successfully.", name),
226		)
227	}
228	
229	func (s *ClassificationAPIServer) readManagedConfigDocument(w http.ResponseWriter) (map[string]any, []byte, bool) {
230		if s.configPath == "" {
231			s.writeErrorResponse(w, http.StatusInternalServerError, "NO_CONFIG_PATH", "Router configPath not set")
232			return nil, nil, false
233		}
234		paths := resolveConfigPersistencePaths(s.configPath)
235		doc, data, err := readConfigDocument(paths.sourcePath)
236		if err != nil {
237			status := http.StatusInternalServerError
238			if os.IsNotExist(err) {
239				status = http.StatusNotFound
240			}
241			s.writeErrorResponse(w, status, "READ_ERROR", fmt.Sprintf("Failed to read router config: %v", err))
242			return nil, nil, false
243		}
244		return doc, data, true
245	}
246	
247	func collectManagedRecipes(doc map[string]any) []managedRecipeRecord {
248		recipes := []managedRecipeRecord{{
249			Name:        string(routerconfig.DefaultRecipeName),
250			Description: "Default routing profile",
251			Routing:     mappingValue(doc["routing"]),
252			Entrypoints: []string{},
253			Source:      managedRecipeSourceDefault,
254			Deletable:   false,
255		}}
256		for _, item := range sequenceValue(doc["recipes"]) {
257			recipe := mappingValue(item)
258			name := strings.TrimSpace(stringValue(recipe["name"]))
259			if name == "" {
260				continue
261			}
262			recipes = append(recipes, managedRecipeRecord{
263				Name:        name,
264				Description: stringValue(recipe["description"]),
265				Routing:     mappingValue(recipe["routing"]),
266				Entrypoints: recipeEntrypointNames(doc, name),
267				Source:      managedRecipeSourceNamed,
268				Deletable:   true,
269			})
270		}
271		return recipes
272	}
273	
274	func findManagedRecipe(doc map[string]any, name string) (managedRecipeRecord, bool) {
275		for _, recipe := range collectManagedRecipes(doc) {
276			if recipe.Name == name {
277				return recipe, true
278			}
279		}
280		return managedRecipeRecord{}, false
281	}
282	
283	func applyRecipeMutation(doc map[string]any, name string, req recipeMutationRequest) (bool, error) {
284		if len(req.Routing) == 0 {
285			return false, fmt.Errorf("routing is required and must not be empty")
286		}
287		if routerconfig.RecipeName(name) == routerconfig.DefaultRecipeName {
288			if req.Description != nil && strings.TrimSpace(*req.Description) != "" {
289				return false, fmt.Errorf("the default recipe has no description field; update its top-level routing block only")
290			}
291			if req.Entrypoints != nil {
292				return false, fmt.Errorf("default recipe aliases are managed by global.router.auto_model_names, not entrypoints")
293			}
294			doc["routing"] = cloneYAMLValue(req.Routing)
295			return false, nil
296		}
297	
298		recipes := sequenceValue(doc["recipes"])
299		replacement := map[string]any{
300			"name":    name,
301			"routing": cloneYAMLValue(req.Routing),
302		}
303		if req.Description != nil && strings.TrimSpace(*req.Description) != "" {
304			replacement["description"] = strings.TrimSpace(*req.Description)
305		}
306	
307		created := true
308		for index, item := range recipes {
309			recipe := mappingValue(item)
310			if strings.TrimSpace(stringValue(recipe["name"])) != name {
311				continue
312			}
313			recipes[index] = replacement
314			created = false
315			break
316		}
317		if created {
318			recipes = append(recipes, replacement)
319		}
320		doc["recipes"] = recipes
321		if req.Entrypoints != nil {
322			replaceRecipeEntrypoints(doc, name, *req.Entrypoints)
323		}
324		return created, nil
325	}
326	
327	func replaceRecipeEntrypoints(doc map[string]any, recipeName string, modelNames []string) {
328		normalized := make([]string, 0, len(modelNames))
329		for _, modelName := range modelNames {
330			modelName = strings.TrimSpace(modelName)
331			if modelName != "" && !slices.Contains(normalized, modelName) {
332				normalized = append(normalized, modelName)
333			}
334		}
335	
336		entrypoints := sequenceValue(doc["entrypoints"])
337		filtered := make([]any, 0, len(entrypoints)+1)
338		inserted := false
339		for _, item := range entrypoints {
340			entrypoint := mappingValue(item)
341			if strings.TrimSpace(stringValue(entrypoint["recipe"])) != recipeName {
342				filtered = append(filtered, item)
343				continue
344			}
345			if !inserted && len(normalized) > 0 {
346				filtered = append(filtered, map[string]any{
347					"model_names": append([]string(nil), normalized...),
348					"recipe":      recipeName,
349				})
350				inserted = true
351			}
352		}
353		if !inserted && len(normalized) > 0 {
354			filtered = append(filtered, map[string]any{
355				"model_names": append([]string(nil), normalized...),
356				"recipe":      recipeName,
357			})
358		}
359		doc["entrypoints"] = filtered
360	}
361	
362	func recipeEntrypointNames(doc map[string]any, recipeName string) []string {
363		var names []string
364		for _, item := range sequenceValue(doc["entrypoints"]) {
365			entrypoint := mappingValue(item)
366			if strings.TrimSpace(stringValue(entrypoint["recipe"])) != recipeName {
367				continue
368			}
369			for _, modelName := range sequenceValue(entrypoint["model_names"]) {
370				name := strings.TrimSpace(stringValue(modelName))
371				if name != "" && !slices.Contains(names, name) {
372					names = append(names, name)
373				}
374			}
375		}
376		return names
377	}
378	
379	func removeNamedRecipe(doc map[string]any, name string) bool {
380		recipes := sequenceValue(doc["recipes"])
381		filtered := make([]any, 0, len(recipes))
382		removed := false
383		for _, item := range recipes {
384			recipe := mappingValue(item)
385			if strings.TrimSpace(stringValue(recipe["name"])) == name {
386				removed = true
387				continue
388			}
389			filtered = append(filtered, item)
390		}
391		if removed {
392			doc["recipes"] = filtered
393		}
394		return removed
395	}
396	
397	func mappingValue(value any) map[string]any {
398		if mapping, ok := value.(map[string]any); ok {
399			return mapping
400		}
401		return map[string]any{}
402	}
403	
404	func sequenceValue(value any) []any {
405		switch sequence := value.(type) {
406		case []any:
407			return sequence
408		case []string:
409			items := make([]any, len(sequence))
410			for index, item := range sequence {
411				items[index] = item
412			}
413			return items
414		default:
415			return []any{}
416		}
417	}
418	
419	func stringValue(value any) string {
420		if value == nil {
421			return ""
422		}
423		return fmt.Sprint(value)
424	}
425	
426	func (s *ClassificationAPIServer) maybeRedactManagedRecipes(
427		r *http.Request,
428		recipes []managedRecipeRecord,
429	) []managedRecipeRecord {
430		if s.canViewSecrets(r) {
431			return recipes
432		}
433		redacted := make([]managedRecipeRecord, len(recipes))
434		copy(redacted, recipes)
435		for index := range redacted {
436			if routing, ok := redactSensitiveConfigValue(redacted[index].Routing).(map[string]any); ok {
437				redacted[index].Routing = routing
438			}
439		}
440		return redacted
441	}
