1	//go:build !windows && cgo
2	
3	package apiserver
4	
5	import (
6		"crypto/sha256"
7		"encoding/hex"
8		"errors"
9		"fmt"
10		"net/http"
11		"os"
12		"path/filepath"
13		"strings"
14		"time"
15	
16		"gopkg.in/yaml.v3"
17	
18		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/config"
19		"github.com/vllm-project/semantic-router/src/semantic-router/pkg/observability/logging"
20	)
21	
22	type routerConfigMutationMode string
23	
24	const (
25		routerConfigMutationMerge   routerConfigMutationMode = "merge"
26		routerConfigMutationReplace routerConfigMutationMode = "replace"
27	)
28	
29	// handleConfigPatch handles PATCH /config/router with merge semantics.
30	func (s *ClassificationAPIServer) handleConfigPatch(w http.ResponseWriter, r *http.Request) {
31		s.handleConfigMutation(w, r, routerConfigMutationMerge)
32	}
33	
34	// handleConfigPut handles PUT /config/router with replace semantics.
35	func (s *ClassificationAPIServer) handleConfigPut(w http.ResponseWriter, r *http.Request) {
36		s.handleConfigMutation(w, r, routerConfigMutationReplace)
37	}
38	
39	func (s *ClassificationAPIServer) handleConfigMutation(
40		w http.ResponseWriter,
41		r *http.Request,
42		mode routerConfigMutationMode,
43	) {
44		if s.configPath == "" {
45			s.writeErrorResponse(w, http.StatusInternalServerError, "NO_CONFIG_PATH", "Router configPath not set")
46			return
47		}
48		if !deployMu.TryLock() {
49			s.writeErrorResponse(w, http.StatusConflict, "DEPLOY_IN_PROGRESS", "Another config update operation is in progress. Please try again.")
50			return
51		}
52		defer deployMu.Unlock()
53	
54		req, patchDoc, ok := s.parseRouterConfigUpdateRequest(w, r)
55		if !ok {
56			return
57		}
58	
59		paths := resolveConfigPersistencePaths(s.configPath)
60		yamlBytes, existingData, ok := s.prepareRouterConfigMutationPayload(w, patchDoc, paths.sourcePath, mode)
61		if !ok {
62			return
63		}
64		if !checkConfigPrecondition(w, r, existingData, false) {
65			return
66		}
67	
68		s.commitRouterConfigDocument(
69			w,
70			paths,
71			existingData,
72			yamlBytes,
73			req.DSL,
74			http.StatusOK,
75			fmt.Sprintf("config.%s", mode),
76			routerConfigMutationMessage(mode),
77		)
78	}
79	
80	func routerConfigMutationMessage(mode routerConfigMutationMode) string {
81		if mode == routerConfigMutationMerge {
82			return "Router config merged successfully."
83		}
84		return "Router config replaced successfully."
85	}
86	
87	func (s *ClassificationAPIServer) parseRouterConfigUpdateRequest(
88		w http.ResponseWriter,
89		r *http.Request,
90	) (RouterConfigUpdateRequest, map[string]any, bool) {
91		var req RouterConfigUpdateRequest
92		if err := s.parseJSONRequest(r, &req); err != nil {
93			s.writeJSONRequestError(w, err)
94			return RouterConfigUpdateRequest{}, nil, false
95		}
96		if strings.TrimSpace(req.YAML) == "" {
97			s.writeErrorResponse(w, http.StatusBadRequest, "INVALID_INPUT", "YAML content is required")
98			return RouterConfigUpdateRequest{}, nil, false
99		}
100	
101		doc, err := decodeYAMLDocument([]byte(req.YAML))
102		if err != nil {
103			s.writeErrorResponse(w, http.StatusBadRequest, "YAML_PARSE_ERROR", fmt.Sprintf("Invalid YAML syntax: %v", err))
104			return RouterConfigUpdateRequest{}, nil, false
105		}
106	
107		return req, doc, true
108	}
109	
110	func (s *ClassificationAPIServer) prepareRouterConfigMutationPayload(
111		w http.ResponseWriter,
112		patchDoc map[string]any,
113		sourceConfigPath string,
114		mode routerConfigMutationMode,
115	) ([]byte, []byte, bool) {
116		existingDoc, existingData, err := readConfigDocument(sourceConfigPath)
117		if err != nil && !os.IsNotExist(err) {
118			s.writeErrorResponse(w, http.StatusInternalServerError, "READ_ERROR", fmt.Sprintf("Failed to read existing config: %v", err))
119			return nil, nil, false
120		}
121	
122		nextDoc := patchDoc
123		if mode == routerConfigMutationMerge {
124			nextDoc = mergeConfigDocuments(existingDoc, patchDoc)
125		}
126	
127		yamlBytes, err := validateAndEncodeRouterConfigDocument(nextDoc)
128		if err != nil {
129			s.writeErrorResponse(w, http.StatusBadRequest, "CONFIG_VALIDATION_ERROR", err.Error())
130			return nil, nil, false
131		}
132		if len(existingData) > 0 {
133			if err := validateHotReloadCompatibility(existingData, yamlBytes); err != nil {
134				s.writeErrorResponse(
135					w,
136					http.StatusConflict,
137					"RESTART_REQUIRED",
138					scrubSecretsInErrorMessage(err.Error()),
139				)
140				return nil, nil, false
141			}
142		}
143	
144		if len(existingData) == 0 {
145			logging.Infof("[RouterConfig] No existing config at path=%s, writing %s document", sourceConfigPath, mode)
146			return yamlBytes, nil, true
147		}
148	
149		logging.Infof(
150			"[RouterConfig] Existing config found: path=%s, size=%d bytes; applying %s update",
151			sourceConfigPath,
152			len(existingData),
153			mode,
154		)
155		return yamlBytes, existingData, true
156	}
157	
158	func validateAndEncodeRouterConfigDocument(doc map[string]any) ([]byte, error) {
159		return normalizeRouterConfigDocument(doc)
160	}
161	
162	func validateHotReloadCompatibility(currentYAML []byte, nextYAML []byte) error {
163		currentCfg, err := config.ParseYAMLBytes(currentYAML)
164		if err != nil {
165			return fmt.Errorf("failed to parse current config for reload validation: %w", err)
166		}
167		nextCfg, err := config.ParseYAMLBytes(nextYAML)
168		if err != nil {
169			return fmt.Errorf("failed to parse next config for reload validation: %w", err)
170		}
171		return config.ValidateLocalClassifierReload(currentCfg, nextCfg)
172	}
173	
174	func normalizeRouterConfigDocument(doc map[string]any) ([]byte, error) {
175		return normalizeRouterConfigDocumentWithParser(doc, config.ParseYAMLBytes)
176	}
177	
178	func normalizeRouterConfigDocumentWithoutEnv(doc map[string]any) ([]byte, error) {
179		return normalizeRouterConfigDocumentWithParser(
180			doc,
181			config.ParseYAMLBytesWithoutEnvExpansion,
182		)
183	}
184	
185	func normalizeRouterConfigDocumentWithParser(
186		doc map[string]any,
187		parse func([]byte) (*config.RouterConfig, error),
188	) ([]byte, error) {
189		rawYAML, err := yaml.Marshal(doc)
190		if err != nil {
191			return nil, fmt.Errorf("failed to encode router config update: %w", err)
192		}
193	
194		if _, err := parse(rawYAML); err != nil {
195			return nil, fmt.Errorf("config validation failed: %w", err)
196		}
197		// The submitted document is already canonical v0.3 because ParseYAMLBytes
198		// rejects legacy layouts. Persist that document rather than exporting the
199		// runtime representation back to YAML: runtime endpoint names and explicit
200		// zero values are implementation details and must not rewrite user intent.
201		return rawYAML, nil
202	}
203	
204	func readConfigDocument(path string) (map[string]any, []byte, error) {
205		data, err := os.ReadFile(path)
206		if err != nil {
207			if os.IsNotExist(err) {
208				return map[string]any{}, nil, err
209			}
210			return nil, nil, err
211		}
212		doc, err := decodeYAMLDocument(data)
213		if err != nil {
214			return nil, nil, err
215		}
216		return doc, data, nil
217	}
218	
219	func decodeYAMLDocument(data []byte) (map[string]any, error) {
220		var doc map[string]any
221		if err := yaml.Unmarshal(data, &doc); err != nil {
222			return nil, fmt.Errorf("failed to decode YAML document: %w", err)
223		}
224		if doc == nil {
225			return map[string]any{}, nil
226		}
227		return doc, nil
228	}
229	
230	func mergeConfigDocuments(base map[string]any, patch map[string]any) map[string]any {
231		merged, ok := mergeYAMLValue(base, patch).(map[string]any)
232		if !ok {
233			return map[string]any{}
234		}
235		return merged
236	}
237	
238	func mergeYAMLValue(base any, patch any) any {
239		if patch == nil {
240			return nil
241		}
242	
243		patchMap, ok := patch.(map[string]any)
244		if !ok {
245			return cloneYAMLValue(patch)
246		}
247	
248		merged := map[string]any{}
249		if baseMap, ok := base.(map[string]any); ok {
250			for key, value := range baseMap {
251				merged[key] = cloneYAMLValue(value)
252			}
253		}
254	
255		for key, value := range patchMap {
256			if value == nil {
257				delete(merged, key)
258				continue
259			}
260			merged[key] = mergeYAMLValue(merged[key], value)
261		}
262		return merged
263	}
264	
265	func cloneYAMLValue(value any) any {
266		switch typed := value.(type) {
267		case map[string]any:
268			cloned := make(map[string]any, len(typed))
269			for key, nested := range typed {
270				cloned[key] = cloneYAMLValue(nested)
271			}
272			return cloned
273		case []any:
274			cloned := make([]any, len(typed))
275			for i, nested := range typed {
276				cloned[i] = cloneYAMLValue(nested)
277			}
278			return cloned
279		default:
280			return typed
281		}
282	}
283	
284	func (s *ClassificationAPIServer) recordRouterConfigArtifacts(sourceConfigPath string, existingData []byte, dsl string) (string, string) {
285		configDir := filepath.Dir(sourceConfigPath)
286		backupDir := filepath.Join(configDir, ".vllm-sr", "config-backups")
287		if err := os.MkdirAll(backupDir, 0o755); err != nil {
288			logging.Warnf("Failed to create backup directory: %v", err)
289		}
290	
291		version := nextConfigVersion(backupDir, time.Now())
292		source := configVersionSourceAPI
293		if strings.TrimSpace(dsl) != "" {
294			source = configVersionSourceDSL
295		}
296		recordConfigBackup(backupDir, version, existingData, source)
297	
298		if strings.TrimSpace(dsl) != "" {
299			dslDir := filepath.Join(configDir, ".vllm-sr")
300			dslFile := filepath.Join(dslDir, "config.dsl")
301			if err := os.WriteFile(dslFile, []byte(dsl), 0o644); err != nil {
302				logging.Warnf("Failed to archive DSL source: %v", err)
303			}
304		}
305	
306		return version, backupDir
307	}
308	
309	func (s *ClassificationAPIServer) writeRouterConfigFiles(
310		w http.ResponseWriter,
311		paths configPersistencePaths,
312		previousData []byte,
313		yamlBytes []byte,
314	) bool {
315		if err := writeConfigAtomically(paths.sourcePath, yamlBytes); err != nil {
316			s.writeErrorResponse(w, http.StatusInternalServerError, "WRITE_ERROR", fmt.Sprintf("Failed to write source config: %v", err))
317			return false
318		}
319	
320		if !paths.usesRuntimeOverride() {
321			return true
322		}
323	
324		if err := syncRuntimeConfigOrRestore(paths, previousData); err != nil {
325			s.writeErrorResponse(w, http.StatusInternalServerError, "RUNTIME_SYNC_ERROR", err.Error())
326			return false
327		}
328		return true
329	}
330	
331	func (s *ClassificationAPIServer) commitRouterConfigDocument(
332		w http.ResponseWriter,
333		paths configPersistencePaths,
334		previousData []byte,
335		yamlBytes []byte,
336		dsl string,
337		statusCode int,
338		action string,
339		message string,
340	) bool {
341		version, backupDir := s.recordRouterConfigArtifacts(paths.sourcePath, previousData, dsl)
342		if !s.writeRouterConfigFiles(w, paths, previousData, yamlBytes) {
343			return false
344		}
345	
346		etag := configDocumentETag(yamlBytes)
347		runtimeHash, runtimeStatus := s.waitForRuntimeConfigActivation(paths.runtimePath)
348		responseStatus := "success"
349		responseCode := statusCode
350		switch runtimeStatus {
351		case "pending":
352			responseStatus = "accepted"
353			responseCode = http.StatusAccepted
354			message += " The config is persisted but runtime activation is still pending; poll /config/hash until status is active."
355		case "active":
356			message += " Runtime activation is complete."
357		default:
358			message += " Router reload will continue asynchronously."
359		}
360		w.Header().Set("ETag", etag)
361		logging.Infof(
362			"Router config mutation committed via API: action=%s, version=%s, size=%d bytes, sourceConfigPath=%s, runtimeConfigPath=%s",
363			action,
364			version,
365			len(yamlBytes),
366			paths.sourcePath,
367			paths.runtimePath,
368		)
369		configCleanupBackups(backupDir)
370		s.writeJSONResponse(w, responseCode, RouterConfigUpdateResponse{
371			Status:        responseStatus,
372			Version:       version,
373			ETag:          etag,
374			RuntimeStatus: runtimeStatus,
375			RuntimeHash:   runtimeHash,
376			Message:       message,
377		})
378		return true
379	}
380	
381	func configFileHash(path string) (string, error) {
382		data, err := os.ReadFile(path)
383		if err != nil {
384			return "", err
385		}
386		digest := sha256.Sum256(data)
387		return hex.EncodeToString(digest[:]), nil
388	}
389	
390	func (s *ClassificationAPIServer) activeConfigDocumentHash() string {
391		if s.runtimeRegistry != nil {
392			if cfg := s.runtimeRegistry.CurrentConfig(); cfg != nil {
393				return cfg.DocumentHash
394			}
395			return ""
396		}
397		if cfg := s.currentConfig(); cfg != nil {
398			return cfg.DocumentHash
399		}
400		return ""
401	}
402	
403	// waitForRuntimeConfigActivation closes the read-after-write gap for the
404	// shared runtime used by the production Router. The file watcher performs all
405	// expensive preparation off to the side and publishes the matching document
406	// hash only after the new router and classification service are atomically
407	// available. Legacy/test servers without a runtime registry keep their
408	// asynchronous behavior.
409	func (s *ClassificationAPIServer) waitForRuntimeConfigActivation(runtimePath string) (string, string) {
410		runtimeHash, err := configFileHash(runtimePath)
411		if err != nil {
412			return "", "unknown"
413		}
414		if s.runtimeRegistry == nil {
415			return runtimeHash, "unknown"
416		}
417	
418		const activationTimeout = 20 * time.Second
419		deadline := time.Now().Add(activationTimeout)
420		for {
421			if s.activeConfigDocumentHash() == runtimeHash {
422				return runtimeHash, "active"
423			}
424			if time.Now().After(deadline) {
425				return runtimeHash, "pending"
426			}
427			time.Sleep(50 * time.Millisecond)
428		}
429	}
430	
431	func syncRuntimeConfigOrRestore(paths configPersistencePaths, previousData []byte) error {
432		_, syncErr := runtimeConfigSyncRunner(paths.sourcePath)
433		if syncErr == nil {
434			return nil
435		}
436		if restoreErr := restoreSourceConfig(paths.sourcePath, previousData); restoreErr != nil {
437			return errors.Join(syncErr, fmt.Errorf("failed to restore source config: %w", restoreErr))
438		}
439		if len(previousData) == 0 {
440			return syncErr
441		}
442		if _, restoreSyncErr := runtimeConfigSyncRunner(paths.sourcePath); restoreSyncErr != nil {
443			return errors.Join(syncErr, fmt.Errorf("source config restored but runtime resync failed: %w", restoreSyncErr))
444		}
445		return syncErr
446	}
447	
448	func restoreSourceConfig(sourcePath string, previousData []byte) error {
449		if len(previousData) > 0 {
450			return writeConfigAtomically(sourcePath, previousData)
451		}
452		if err := os.Remove(sourcePath); err != nil && !os.IsNotExist(err) {
453			return err
454		}
455		return nil
456	}
457	
458	func writeConfigAtomically(configPath string, yamlBytes []byte) error {
459		tmpConfigFile := configPath + ".tmp"
460		if err := os.WriteFile(tmpConfigFile, yamlBytes, 0o644); err != nil {
461			return err
462		}
463		if err := os.Rename(tmpConfigFile, configPath); err != nil {
464			if writeErr := os.WriteFile(configPath, yamlBytes, 0o644); writeErr != nil {
465				return writeErr
466			}
467		}
468		return nil
469	}
