11		ManagementInternalListenerEnv = "VLLM_SR_MANAGEMENT_INTERNAL_LISTENER"
12	
13		ManagementAuthModeBearer   = "bearer"
14		ManagementAuthModeDisabled = "disabled"
15	
16		ManagementPermWildcard = "*"
17	)
18	
19	// ManagementAPIConfig configures the router management HTTP listener (#2463).
20	// Listener on/off is controlled by the legacy -enable-api flag at startup, not
21	// by a config enabled field.
22	type ManagementAPIConfig struct {
23		BindAddress    string                  `yaml:"bind_address,omitempty"`
24		Port           int                     `yaml:"port,omitempty"`
25		RemoteExposure bool                    `yaml:"remote_exposure,omitempty"`
26		Auth           ManagementAPIAuthConfig `yaml:"auth,omitempty"`
27	}
28	
29	// ManagementAPIAuthConfig controls authentication for non-health management routes.
30	type ManagementAPIAuthConfig struct {
31		Mode   string                  `yaml:"mode,omitempty"`
32		Tokens []ManagementAPITokenRef `yaml:"tokens,omitempty"`
33		Roles  map[string][]string     `yaml:"roles,omitempty"`
34	}
35	
36	// ManagementAPITokenRef binds a bearer token from an environment variable to a role.
37	type ManagementAPITokenRef struct {
38		Env  string `yaml:"env,omitempty"`
39		Role string `yaml:"role,omitempty"`
40	}
41	
42	// ManagementAPIRuntimeOptions carries CLI overrides for management listener startup.
43	type ManagementAPIRuntimeOptions struct {
44		Port           int
45		BindAddress    string
46		RemoteExposure *bool
47		AuthMode       string
48	}
49	
50	// DefaultManagementAPIConfig returns safe local defaults for the management listener.
51	func DefaultManagementAPIConfig() ManagementAPIConfig {
52		return ManagementAPIConfig{
53			BindAddress:    "127.0.0.1",
54			Port:           8080,
55			RemoteExposure: false,
56			Auth: ManagementAPIAuthConfig{
57				Mode:  ManagementAuthModeDisabled,
58				Roles: DefaultManagementAPIRoles(),
59			},
60		}
61	}
62	
63	// DefaultManagementAPIRoles returns the built-in role-to-permission map.
64	//
65	// secret_view is admin-only (via ManagementPermWildcard). Viewer and operator
66	// may call config.read routes such as GET /config/router, but secret fields are
67	// redacted unless the principal has secret_view.
68	//
69	// Keep config/config.yaml global.services.management_api.auth.roles aligned with
70	// these defaults; reference-config tests enforce that contract.
71	func DefaultManagementAPIRoles() map[string][]string {
72		return map[string][]string{
73			"viewer": {
74				"health.read",
75				"ready.read",
